<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsToMany;use Illuminate\Database\Eloquent\Relations\HasMany;class Conversation extends Model{protected $fillable=['tenant_id','event_id','type','subject'];public function participants():BelongsToMany{return $this->belongsToMany(User::class,'conversation_participants')->withPivot(['last_read_at','muted'])->withTimestamps();}public function messages():HasMany{return $this->hasMany(Message::class);}}
